from functools import lru_cache

calls = []


@lru_cache(maxsize=None)
def fib(n):
    calls.append(n)
    return n if n < 2 else fib(n - 1) + fib(n - 2)


print(fib(30))
print(sorted(calls) == list(range(31)))

from functools import singledispatch


@singledispatch
def render(x):
    return f"默认：{type(x).__name__}"


@render.register
def _(x: int):
    return f"整数 {x}"


@render.register
def _(x: str):
    return f"字符串 {x}"


print(render(7))
print(render("hi"))
print(render(1.5))
